draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.stroke();

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 90);
  ctx.lineTo(W/2 - 25, H/2 - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 90);
  ctx.lineTo(W/2 + 25, H/2 - 70);
  ctx.stroke();

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 8, H/2 - 60, 2, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 8, H/2 - 60, 2, 0, 2 * Math.PI);
  ctx.stroke();

  // yawn
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 40, 10 + 5 * Math.sin(t), 0, Math.PI);
  ctx.stroke();

  // lip lick
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 - 30);
  ctx.lineTo(W/2 - 10 + 10 * Math.cos(t), H/2 - 20);
  ctx.stroke();

  ctx.restore();
}
